    test(
      'pkill -f does not kill its own bash tool shell (foreground)',
      skip: Platform.isWindows ? 'POSIX process semantics only' : false,
      () async {
        final result = await const LocalShell().exec(
          'pkill -f fa_self_match_tok_1763; echo survived',
