      // never ship one).
      for (final entry in overlay.entries) {
        if (given == null || !given.containsKey(entry.key)) {
          base[entry.key] = entry.value;
        }
      }
      if (shimDir != null) {
        base['PATH'] = '$shimDir:${base['PATH'] ?? ''}';
      }
    }
    return base;
  }

