{"newText":"  group('AC2c: guard provisioning hardening (gh-1763 review)', () {
    test(
      'a failing chmod degrades to a shimless provision instead of '
      'bricking pkill',
      skip: Platform.isWindows
          ? 'the guard is POSIX-only'
          : false,
      () async {
        // `false` exits 1: the shim file stays non-executable. The shim
        // must be dropped (degrade-to-null pathway) — handing the child a
        // non-executable `pkill` would turn every later pkill/killall
        // call into "Permission denied" instead of degrading to the real
        // binary. The pid set stays armed for the `kill()` prelude.
        final provision = await provisionBashGuard(chmodCommand: 'false');
        expect(
          provision,
          isNotNull,
          reason: 'the pid set must stay armed for the kill() prelude',
        );
        expect(provision!.protectedPids, contains(pid));
        expect(
          provision.shimDir,
          isNull,
          reason:
              'a shim the child cannot exec is worse than no shim — it '
              'must be dropped from the provision',
        );
      },
    );

    test(
      'a successful chmod keeps the shim dir provisioned',
      skip: Platform.isWindows || !hostHasPgrep
          ? 'the shims need procps (pgrep) on the host'
          : false,
      () async {
        final provision = await provisionBashGuard();
        expect(provision, isNotNull);
        expect(provision!.shimDir, isNotNull);
        expect(provision.protectedPids, contains(pid));
      },
    );
  });

  group('E3: sh -c delivery parity (gh-1763)', () {","oldText":"  group('E3: sh -c delivery parity (gh-1763)', () {","path":"test/env/bash_self_defense_test.dart"}

{"newText":"/// Provisions the guard once per process. POSIX only — null on Windows and
/// on any failure (never throws). [chmodCommand] exists for tests: it lets
/// a suite force the chmod step to fail (`false`) and pin the
/// degrade-to-no-shim behavior.
Future<BashGuardProvision?> provisionBashGuard({String chmodCommand = 'chmod'}) async {
  if (Platform.isWindows) return null;
  try {
    final pids = await _protectedPidChain();
    final shims = await _buildShimScripts();
    final shimDir = shims.isEmpty
        ? null
        : await _writeShimDir(shims, chmodCommand: chmodCommand);
    return BashGuardProvision(shimDir: shimDir, protectedPids: pids);
  } on Object {
    return null;
  }
}","oldText":"/// Provisions the guard once per process. POSIX only — null on Windows and
