{"command":"cat > scratch_probe.dart <<'EOF'
import 'dart:io';
import 'package:flutter_agent_harness/io.dart';
Future<void> main(List<String> args) async {
  final pgid = args[0]; // a live setsid sleep's pgid
  final env = {'FA_PROTECTED_PIDS': pgid};
  // kill -- -PGID (protected) must NOT signal the group
  var r = await Process.run('sh', ['-c', '. /dev/stdin <<\'PRELUDE\'\n'
      '${bashGuardPrelude()}\nPRELUDE\n'
      'kill -- -$pgid; echo "rc=\$?"'],
      environment: env);
  print('protected  -- -PGID: rc=${r.exitCode} out=${r.stdout} err=${(r.stderr as String).trim()}');
  r = await Process.run('sh', ['-c', '. /dev/stdin <<\'PRELUDE\'\n'
      '${bashGuardPrelude()}\nPRELUDE\n'
      'kill -9 -- -$pgid 999999 2>/dev/null; echo "rc=\$?"'],
      environment: env);
  print('mixed(protected pgid + bogus pid): rc=${r.exitCode} out=${r.stdout} err=${(r.stderr as String).trim()}');
  r = await Process.run('sh', ['-c', '. /dev/stdin <<\'PRELUDE\'\n'
      '${bashGuardPrelude()}\nPRELUDE\n'
      'kill -- -$pgid; echo "rc=\$?"'],
      environment: {'FA_PROTECTED_PIDS': '4242'});
  print('unprotected -- -PGID: rc=${r.exitCode} out=${r.stdout} err=${(r.stderr as String).trim()}');
}
EOF
